head.b:skin:
:root {
    --bg-dark: #090d0a;
    --bg-card: rgba(18, 26, 20, 0.75);
    --border-color: rgba(34, 197, 94, 0.2);
    --border-hover: rgba(34, 197, 94, 0.5);
    --accent-green: #22c55e;
    --accent-green-dark: #16a34a;
    --accent-glow: rgba(34, 197, 94, 0.35);
    --text-main: #f3f4f6;
    --text-muted: #9ca3af;
    --card-radius: 16px;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: 'Plus Jakarta Sans', sans-serif;
}

body {
    background-color: var(--bg-dark);
    background-image:
        radial-gradient(circle at 50% 0%, rgba(34, 197, 94, 0.12), transparent 50%),
        radial-gradient(circle at 80% 80%, rgba(16, 185, 129, 0.05), transparent 40%);
    background-attachment: fixed;
    color: var(--text-main);
    min-height: 100vh;
    overflow-x: hidden;
    line-height: 1.5;
}

/* Top Announcement Banner */
.top-banner {
    background: rgba(34, 197, 94, 0.08);
    border-bottom: 1px solid var(--border-color);
    padding: 10px 16px;
    font-size: 0.85rem;
    text-align: center;
    color: var(--accent-green);
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 10px;
    font-weight: 600;
}

.pulse-dot {
    width: 8px;
    height: 8px;
    background: var(--accent-green);
    border-radius: 50%;
    box-shadow: 0 0 10px var(--accent-green);
    animation: pulse 1.5s infinite;
}

@keyframes pulse {
    0% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(34, 197, 94, 0.7); }
    70% { transform: scale(1); box-shadow: 0 0 0 8px rgba(34, 197, 94, 0); }
    100% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(34, 197, 94, 0); }
}

/* Navigation */
nav {
    max-width: 1200px;
    margin: 0 auto;
    padding: 20px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 20px;
}

.logo {
    font-family: 'Space Grotesk', sans-serif;
    font-size: 1.6rem;
    font-weight: 700;
    color: #fff;
    display: flex;
    align-items: center;
    gap: 10px;
    text-decoration: none;
}

.logo i { color: var(--accent-green); }

.nav-actions {
    display: flex;
    align-items: center;
    gap: 12px;
}

.search-box {
    position: relative;
    display: flex;
    align-items: center;
}

.search-box input {
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.1);
    padding: 8px 16px 8px 36px;
    border-radius: 20px;
    color: #fff;
    font-size: 0.85rem;
    outline: none;
    transition: all 0.2s;
    width: 200px;
}

.search-box input:focus {
    border-color: var(--accent-green);
    width: 240px;
    background: rgba(255, 255, 255, 0.08);
}

.search-box i {
    position: absolute;
    left: 12px;
    color: var(--text-muted);
    font-size: 0.85rem;
}

.trust-badge {
    display: flex;
    align-items: center;
    gap: 8px;
    background: rgba(255,255,255,0.05);
    padding: 8px 14px;
    border-radius: 20px;
    border: 1px solid rgba(255,255,255,0.1);
    font-size: 0.8rem;
    color: var(--text-muted);
    white-space: nowrap;
}

/* Hero Header */
.hero {
    text-align: center;
    max-width: 800px;
    margin: 40px auto 30px;
    padding: 0 20px;
}

.hero-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: rgba(34, 197, 94, 0.1);
    border: 1px solid var(--border-color);
    padding: 4px 12px;
    border-radius: 20px;
    font-size: 0.8rem;
    color: var(--accent-green);
    margin-bottom: 16px;
    font-weight: 600;
}

.hero h1 {
    font-family: 'Space Grotesk', sans-serif;
    font-size: 2.8rem;
    line-height: 1.2;
    margin-bottom: 15px;
    background: linear-gradient(180deg, #ffffff 0%, #a7f3d0 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.hero p {
    color: var(--text-muted);
    font-size: 1.1rem;
    line-height: 1.6;
}

/* Category Filter Bar */
.filter-bar {
    max-width: 1200px;
    margin: 0 auto 30px;
    padding: 0 20px;
    display: flex;
    justify-content: center;
    gap: 10px;
    flex-wrap: wrap;
}

.filter-btn {
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.08);
    color: var(--text-muted);
    padding: 8px 18px;
    border-radius: 20px;
    font-size: 0.85rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
    display: flex;
    align-items: center;
    gap: 6px;
}

.filter-btn:hover {
    background: rgba(255, 255, 255, 0.08);
    color: #fff;
}

.filter-btn.active {
    background: rgba(34, 197, 94, 0.15);
    border-color: var(--accent-green);
    color: var(--accent-green);
}

/* World Cards Grid */
.grid-container {
    max-width: 1200px;
    margin: 0 auto 60px;
    padding: 0 20px;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: 25px;
}

.world-card {
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    border-radius: var(--card-radius);
    overflow: hidden;
    backdrop-filter: blur(12px);
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    position: relative;
    display: flex;
    flex-direction: column;
}

.world-card:hover {
    transform: translateY(-6px);
    border-color: var(--border-hover);
    box-shadow: 0 16px 32px -10px var(--accent-glow);
}

.card-img-wrap {
    position: relative;
    height: 200px;
    overflow: hidden;
    background: #000;
}

.card-img-wrap img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease, filter 0.3s ease;
    filter: brightness(0.9) contrast(1.05);
}

.world-card:hover .card-img-wrap img {
    transform: scale(1.06);
    filter: brightness(1) contrast(1.1);
}

.version-tag {
    position: absolute;
    top: 12px;
    right: 12px;
    background: rgba(0,0,0,0.8);
    backdrop-filter: blur(6px);
    border: 1px solid rgba(255,255,255,0.2);
    padding: 4px 10px;
    border-radius: 8px;
    font-size: 0.75rem;
    font-weight: 700;
    color: #fff;
    letter-spacing: 0.02em;
}

.card-badge {
    position: absolute;
    top: 12px;
    left: 12px;
    background: var(--accent-green);
    color: #000;
    padding: 3px 8px;
    border-radius: 6px;
    font-size: 0.7rem;
    font-weight: 800;
    text-transform: uppercase;
}

.card-body {
    padding: 22px;
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.card-title {
    font-size: 1.25rem;
    font-weight: 700;
    margin-bottom: 8px;
    color: #fff;
}

.card-desc {
    font-size: 0.88rem;
    line-height: 1.5;
    color: var(--text-muted);
    margin-bottom: 16px;
    flex-grow: 1;
}

.card-stats {
    display: flex;
    align-items: center;
    justify-content: space-between;
    font-size: 0.82rem;
    color: var(--text-muted);
    margin-bottom: 18px;
    padding-top: 12px;
    border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.card-stats-group {
    display: flex;
    gap: 14px;
}

.card-stats i { color: var(--accent-green); }

.dl-btn {
    width: 100%;
    padding: 12px 16px;
    background: linear-gradient(135deg, #22c55e 0%, #16a34a 100%);
    border: none;
    border-radius: 10px;
    color: #fff;
    font-weight: 700;
    font-size: 0.95rem;
    cursor: pointer;
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 8px;
    transition: all 0.2s ease;
    text-decoration: none;
    box-shadow: 0 4px 15px rgba(34, 197, 94, 0.25);
}

.dl-btn:hover {
    filter: brightness(1.1);
    box-shadow: 0 6px 20px rgba(34, 197, 94, 0.45);
}

.dl-btn.secondary {
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.15);
    box-shadow: none;
    color: var(--text-main);
}

.dl-btn.secondary:hover {
    background: rgba(255,255,255,0.12);
    border-color: rgba(255,255,255,0.25);
}

/* Features Section */
.features-section {
    max-width: 1200px;
    margin: 60px auto;
    padding: 0 20px;
}

.section-header {
    text-align: center;
    margin-bottom: 40px;
}

.section-header h2 {
    font-family: 'Space Grotesk', sans-serif;
    font-size: 2rem;
    margin-bottom: 10px;
}

.section-header p {
    color: var(--text-muted);
    font-size: 0.95rem;
}

.features-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: 20px;
}

.feature-card {
    background: rgba(255, 255, 255, 0.02);
    border: 1px solid rgba(255, 255, 255, 0.06);
    padding: 24px;
    border-radius: 14px;
    text-align: center;
}

.feature-icon {
    width: 48px;
    height: 48px;
    background: rgba(34, 197, 94, 0.1);
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 16px;
    color: var(--accent-green);
    font-size: 1.25rem;
}

.feature-card h3 {
    font-size: 1.05rem;
    margin-bottom: 8px;
}

.feature-card p {
    font-size: 0.85rem;
    color: var(--text-muted);
    line-height: 1.5;
}

/* FAQ Accordion Section */
.faq-section {
    max-width: 800px;
    margin: 60px auto 80px;
    padding: 0 20px;
}

.faq-item {
    background: rgba(255, 255, 255, 0.02);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 12px;
    margin-bottom: 12px;
    overflow: hidden;
}

.faq-question {
    padding: 18px 20px;
    font-weight: 600;
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 0.95rem;
    user-select: none;
}

.faq-question i {
    transition: transform 0.3s;
    color: var(--accent-green);
}

.faq-answer {
    padding: 0 20px 18px;
    font-size: 0.88rem;
    color: var(--text-muted);
    line-height: 1.6;
    display: none;
}

.faq-item.active .faq-answer {
    display: block;
}

.faq-item.active .faq-question i {
    transform: rotate(180deg);
}

/* Footer */
footer {
    background: rgba(0, 0, 0, 0.5);
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    padding: 40px 20px 80px;
    text-align: center;
    font-size: 0.85rem;
    color: var(--text-muted);
}

.footer-content {
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
}

.footer-disclaimer {
    font-size: 0.75rem;
    color: #6b7280;
    max-width: 600px;
    line-height: 1.4;
}

/* Modal / Download Window */
.modal-overlay {
    position: fixed;
    top: 0; left: 0; width: 100%; height: 100%;
    background: rgba(0,0,0,0.85);
    backdrop-filter: blur(10px);
    display: none;
    justify-content: center;
    align-items: center;
    z-index: 1000;
    padding: 15px;
}

.modal-card {
    background: #111813;
    border: 1px solid var(--border-color);
    width: 100%;
    max-width: 480px;
    border-radius: 20px;
    padding: 28px;
    box-shadow: 0 25px 50px -12px rgba(0,0,0,0.8);
    position: relative;
    animation: modalUp 0.3s ease-out;
    max-height: 90vh;
    overflow-y: auto;
}

@keyframes modalUp {
    from { opacity: 0; transform: translateY(20px); }
    to { opacity: 1; transform: translateY(0); }
}

.modal-close {
    position: absolute;
    top: 20px; right: 20px;
    color: var(--text-muted);
    cursor: pointer;
    font-size: 1.2rem;
    transition: color 0.2s;
    z-index: 10;
}

.modal-close:hover { color: #fff; }

.step-indicator {
    display: flex;
    justify-content: space-between;
    margin-bottom: 25px;
    position: relative;
    max-width: 200px;
    margin: 0 auto 25px;
}

.step-indicator::before {
    content: '';
    position: absolute;
    top: 50%; left: 0; width: 100%; height: 2px;
    background: rgba(255,255,255,0.1);
    z-index: 1;
}

.step {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: #1f2922;
    border: 2px solid rgba(255,255,255,0.1);
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    font-size: 0.85rem;
    position: relative;
    z-index: 2;
    color: var(--text-muted);
}

.step.active {
    background: var(--accent-green);
    border-color: var(--accent-green);
    color: #fff;
    box-shadow: 0 0 15px var(--accent-glow);
}

.edition-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 10px;
    margin-top: 10px;
}

.edition-option {
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    padding: 14px 6px;
    text-align: center;
    cursor: pointer;
    transition: all 0.2s ease;
    color: var(--text-muted);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    font-size: 0.8rem;
    font-weight: 700;
    user-select: none;
}

.edition-option i { font-size: 1.3rem; }

.edition-option:hover {
    background: rgba(255, 255, 255, 0.08);
    border-color: rgba(255, 255, 255, 0.2);
    color: #fff;
}

.edition-option.active {
    background: rgba(34, 197, 94, 0.12);
    border-color: var(--accent-green);
    color: var(--accent-green);
    box-shadow: 0 0 15px rgba(34, 197, 94, 0.2);
}

.file-info-box {
    background: rgba(34, 197, 94, 0.08);
    border: 1px dashed var(--accent-green);
    padding: 14px 16px;
    border-radius: 12px;
    margin: 20px 0;
    font-size: 0.85rem;
    line-height: 1.5;
    color: #d1d5db;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.file-info-box span strong {
    color: #fff;
    display: block;
    font-size: 0.95rem;
}

.support-step { display: none; text-align: center; }

.support-step > i.headline-icon {
    font-size: 2.2rem;
    color: var(--accent-green);
    margin-bottom: 10px;
}

.support-note {
    font-size: 0.85rem;
    color: var(--text-muted);
    line-height: 1.5;
    margin: 8px 0 20px;
}

.support-options {
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin-bottom: 16px;
}

.support-divider {
    display: flex;
    align-items: center;
    gap: 10px;
    color: var(--text-muted);
    font-size: 0.75rem;
    margin: 12px 0;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.support-divider::before,
.support-divider::after {
    content: '';
    flex: 1;
    height: 1px;
    background: rgba(255,255,255,0.1);
}

.skip-link {
    display: inline-block;
    text-align: center;
    font-size: 0.8rem;
    color: var(--text-muted);
    margin-top: 10px;
    cursor: pointer;
    text-decoration: underline;
    text-underline-offset: 3px;
}

.skip-link:hover { color: var(--text-main); }

/* Floating Live Status Ticker */
.live-ticker {
    position: fixed;
    bottom: 20px;
    left: 20px;
    background: rgba(17, 24, 19, 0.92);
    border: 1px solid var(--border-color);
    padding: 10px 18px;
    border-radius: 30px;
    backdrop-filter: blur(10px);
    display: flex;
    align-items: center;
    gap: 10px;
    font-size: 0.8rem;
    box-shadow: 0 10px 25px rgba(0,0,0,0.5);
    z-index: 100;
    animation: slideIn 0.5s ease;
    max-width: 90vw;
}

@keyframes slideIn {
    from { transform: translateX(-100%); opacity: 0; }
    to { transform: translateX(0); opacity: 1; }
}

/* Mobile Responsive Adjustments */
@media (max-width: 768px) {
    .hero h1 { font-size: 2.2rem; }
    .hero p { font-size: 1rem; }
    .grid-container { grid-template-columns: 1fr; }
    .search-box input { width: 140px; }
    .search-box input:focus { width: 170px; }
}

@media (max-width: 480px) {
    nav {
        flex-direction: column;
        align-items: stretch;
        gap: 12px;
    }
    .nav-actions {
        justify-content: space-between;
        width: 100%;
    }
    .hero h1 { font-size: 1.8rem; }
    .hero { margin: 20px auto; }
    .live-ticker { display: none; }
    .modal-card { padding: 20px; }
    .edition-grid { grid-template-columns: 1fr; }
    .edition-option { flex-direction: row; justify-content: center; }
}

body.script:
//
    // World File Mapping Registry
    const mapFiles = {
        "Skyblock Pro Ultimate": {
            size: { Bedrock: "14 MB", Java: "16 MB", Pocket: "12 MB" },
            ext:  { Bedrock: ".mcworld", Java: ".zip", Pocket: ".mcworld" },
            url:  { Bedrock: "#", Java: "#", Pocket: "#" }
        },
        "Ultra Modern City v4": {
            size: { Bedrock: "112 MB", Java: "128 MB", Pocket: "94 MB" },
            ext:  { Bedrock: ".mcworld", Java: ".zip", Pocket: ".mcworld" },
            url:  { Bedrock: "#", Java: "#", Pocket: "#" }
        },
        "Medieval Kingdom RPG": {
            size: { Bedrock: "85 MB", Java: "90 MB", Pocket: "70 MB" },
            ext:  { Bedrock: ".mcworld", Java: ".zip", Pocket: ".mcworld" },
            url:  { Bedrock: "#", Java: "#", Pocket: "#" }
        },
        "Zombie Apocalypse City": {
            size: { Bedrock: "44 MB", Java: "48 MB", Pocket: "36 MB" },
            ext:  { Bedrock: ".mcworld", Java: ".zip", Pocket: ".mcworld" },
            url:  { Bedrock: "#", Java: "#", Pocket: "#" }
        },
        "One Block Survival Extreme": {
            size: { Bedrock: "8 MB", Java: "9 MB", Pocket: "6 MB" },
            ext:  { Bedrock: ".mcworld", Java: ".zip", Pocket: ".mcworld" },
            url:  { Bedrock: "#", Java: "#", Pocket: "#" }
        },
        "Cyberpunk Neon Metro": {
            size: { Bedrock: "96 MB", Java: "105 MB", Pocket: "88 MB" },
            ext:  { Bedrock: ".mcworld", Java: ".zip", Pocket: ".mcworld" },
            url:  { Bedrock: "#", Java: "#", Pocket: "#" }
        }
    };

    let activeMapName = "";
    let activeEdition = "Bedrock";

    function openFlow(mapName) {
        activeMapName = mapName;
        activeEdition = "Bedrock";

        document.getElementById('selectedMapTitle').innerText = mapName;
        document.getElementById('downloadModal').style.display = 'flex';

        // Reset step state
        document.getElementById('step1-content').style.display = 'block';
        document.getElementById('step2-content').style.display = 'none';
        document.getElementById('st1').className = "step active";
        document.getElementById('st2').className = "step";

        // Reset edition UI
        const options = document.querySelectorAll('.edition-option');
        options.forEach(opt => opt.classList.remove('active'));
        if (options.length > 0) options[0].classList.add('active');

        updateFileInfo();
    }

    function closeFlow() {
        document.getElementById('downloadModal').style.display = 'none';
    }

    function selectEdition(element, editionValue) {
        document.querySelectorAll('.edition-option').forEach(opt => opt.classList.remove('active'));
        element.classList.add('active');
        activeEdition = editionValue;
        updateFileInfo();
    }

    function updateFileInfo() {
        const data = mapFiles[activeMapName];
        if (!data) return;

        document.getElementById('selectedEditionLabel').innerHTML = `<strong>${activeEdition} Edition</strong>`;
        document.getElementById('fileExtension').innerText = `Format: ${data.ext[activeEdition]}`;
        document.getElementById('selectedFileSize').innerText = data.size[activeEdition];

        const link = document.getElementById('realDownloadLink');
        link.href = data.url[activeEdition];
    }

    function goToSupportStep() {
        document.getElementById('step1-content').style.display = 'none';
        document.getElementById('step2-content').style.display = 'block';
        document.getElementById('st2').className = "step active";
    }

    function recordDownload() {
        const ticker = document.getElementById('tickerText');
        if (!activeMapName) return;

        ticker.innerHTML = `Downloading <strong>${activeMapName}</strong> (${activeEdition} Edition)`;
    }

    // Category Filter Handler
    function filterCategory(category, btn) {
        document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        const cards = document.querySelectorAll('.world-card');
        cards.forEach(card => {
            if (category === 'all' || card.dataset.category === category) {
                card.style.display = 'flex';
            } else {
                card.style.display = 'none';
            }
        });
    }

    // Search Input Filter Handler
    function filterMaps() {
        const query = document.getElementById('searchInput').value.toLowerCase();
        const cards = document.querySelectorAll('.world-card');

        cards.forEach(card => {
            const mapName = card.dataset.name;
            if (mapName.includes(query)) {
                card.style.display = 'flex';
            } else {
                card.style.display = 'none';
            }
        });
    }

    // FAQ Accordion Handler
    function toggleFaq(element) {
        const parent = element.parentElement;
        parent.classList.toggle('active');
    }

    // Keyboard & Overlay Click Modal Close
    document.getElementById('downloadModal').addEventListener('click', function (e) {
        if (e.target === this) closeFlow();
    });
    document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape') closeFlow();
    });
//
